native main {
  let score: int = 45;
  if (score >= 60) {
    println("pass");
  } else {
    println("try again");
  }
}

native main {
  let number: int = 1;
  let total: int = 0;
  while (number <= 5) {
    total = total + number;
    number = number + 1;
  }
  println(total);
}

fn triple(value: int): int {
  return value * 3;
}

native main {
  println(triple(4));
  println(triple(7));
}

import strings;

native main {
  let name: string = "Ada";
  println(str_concat("Hello, ", name));
  println(str_len(name));
}

native main {
  let value: int = 9007199254740993;
  println(value);
  println(value + 2);
}

fn ticket_total(price: int, count: int): int {
  return price * count;
}

native main {
  let customer: int = 0;
  let revenue: int = 0;
  while (customer < 2) {
    revenue = revenue + ticket_total(5, 2);
    customer = customer + 1;
  }
  println(revenue);
  if (revenue >= 25) {
    println("target reached");
  } else {
    println("keep going");
  }
}
